/**
 * Arithmetic in the Rijndael finite field GF(2^8).
 *
 * Every byte is treated as a polynomial over GF(2); multiplication is carried
 * out modulo the irreducible polynomial m(x) = x^8 + x^4 + x^3 + x + 1, which
 * is 0x11b.  This module is the lowest layer of the AES implementation: the
 * S-box, the key schedule and MixColumns are all expressed in terms of it.
 */

/** The AES reduction polynomial, without its x^8 term. */
export const AES_POLYNOMIAL = 0x1b;

/**
 * Multiply `a` by x (i.e. by 2) in GF(2^8).
 *
 * @param {number} a byte
 * @returns {number} byte
 */
export function xtime(a) {
  const shifted = (a << 1) & 0xff;
  return a & 0x80 ? shifted ^ AES_POLYNOMIAL : shifted;
}

/**
 * Multiply two bytes in GF(2^8) using the peasant algorithm.
 *
 * @param {number} a byte
 * @param {number} b byte
 * @returns {number} byte
 */
export function gmul(a, b) {
  let result = 0;
  let x = a & 0xff;
  let y = b & 0xff;
  while (y) {
    if (y & 1) result ^= x;
    x = xtime(x);
    y >>= 1;
  }
  return result & 0xff;
}

/**
 * Discrete exponential/logarithm tables for the generator 0x03.  `EXP[i]` is
 * 0x03^i and `LOG[EXP[i]]` is `i`; together they give a cheap multiplicative
 * inverse, which is what the S-box is built from.
 */
const EXP = new Uint8Array(256);
const LOG = new Uint8Array(256);

{
  let x = 1;
  for (let i = 0; i < 255; i += 1) {
    EXP[i] = x;
    LOG[x] = i;
    // multiply by the generator 3 == x + 1  =>  x*2 ^ x
    x = (xtime(x) ^ x) & 0xff;
  }
  EXP[255] = EXP[0];
}

/**
 * Multiplicative inverse in GF(2^8).  Zero is mapped to zero, as Rijndael
 * defines it.
 *
 * @param {number} a byte
 * @returns {number} byte
 */
export function ginv(a) {
  const b = a & 0xff;
  return b === 0 ? 0 : EXP[255 - LOG[b]];
}

/**
 * Rotate a byte left by `n` bits.
 *
 * @param {number} a byte
 * @param {number} n bit count
 * @returns {number} byte
 */
export function rotl8(a, n) {
  return ((a << n) | (a >>> (8 - n))) & 0xff;
}

