/**
 * The AES substitution boxes and round constants.
 *
 * Nothing here is hard-coded: every table is derived at module load time from
 * the GF(2^8) primitives in `galois.mjs`, exactly the way FIPS-197 defines
 * them.  Deriving rather than transcribing removes a whole class of typo bugs
 * and keeps the tables auditable.
 */

import { ginv, rotl8, xtime } from './galois.mjs';

/** Forward substitution box (SubBytes). */
export const SBOX = new Uint8Array(256);

/** Inverse substitution box (InvSubBytes). */
export const INV_SBOX = new Uint8Array(256);

{
  for (let i = 0; i < 256; i += 1) {
    const inv = ginv(i);
    // Affine transform over GF(2): s = inv ^ rotl(inv,1) ^ ... ^ rotl(inv,4) ^ 0x63
    const s =
      (inv ^ rotl8(inv, 1) ^ rotl8(inv, 2) ^ rotl8(inv, 3) ^ rotl8(inv, 4) ^ 0x63) & 0xff;
    SBOX[i] = s;
    INV_SBOX[s] = i;
  }
}

/**
 * Round constants used by the key schedule.  `RCON[i]` is x^i in GF(2^8);
 * fourteen entries are enough for AES-128/192/256 (10/8/7 are actually used).
 */
export const RCON = new Uint8Array(14);

{
  let value = 1;
  for (let i = 0; i < RCON.length; i += 1) {
    RCON[i] = value;
    value = xtime(value);
  }
}

