/**
 * AES key expansion (FIPS-197 section 5.2).
 *
 * The cipher key is expanded into `4 * (Nr + 1)` 32-bit words, which the block
 * cipher consumes as `Nr + 1` sixteen-byte round keys.
 */

import { RCON, SBOX } from './tables.mjs';
import { ValueError } from '../python/errors.mjs';

/** Number of rounds keyed by the cipher key length in bytes. */
const ROUNDS_BY_KEY_SIZE = new Map([
  [16, 10],
  [24, 12],
  [32, 14],
]);

/** Key lengths in bytes that AES accepts, in ascending order. */
export const VALID_KEY_SIZES = [16, 24, 32];

/**
 * @typedef {object} KeySchedule
 * @property {Uint8Array} words flat expanded key, `16 * (rounds + 1)` bytes
 * @property {number} rounds number of cipher rounds (Nr)
 */

/**
 * Expand a cipher key into its round keys.
 *
 * @param {Uint8Array} key 16, 24 or 32 raw key bytes
 * @returns {KeySchedule}
 * @throws {ValueError} when the key length is not one AES accepts
 */
export function expandKey(key) {
  const rounds = ROUNDS_BY_KEY_SIZE.get(key.length);
  if (rounds === undefined) {
    throw new ValueError('Invalid key size');
  }

  const nk = key.length / 4; // key length in 32-bit words
  const wordCount = 4 * (rounds + 1);
  const words = new Uint8Array(wordCount * 4);
  words.set(key, 0);

  let rconIndex = 0;
  for (let i = nk; i < wordCount; i += 1) {
    const prev = (i - 1) * 4;
    let t0 = words[prev];
    let t1 = words[prev + 1];
    let t2 = words[prev + 2];
    let t3 = words[prev + 3];

    if (i % nk === 0) {
      // RotWord, then SubWord, then XOR the round constant into the first byte.
      const rotated = t0;
      t0 = SBOX[t1] ^ RCON[rconIndex];
      t1 = SBOX[t2];
      t2 = SBOX[t3];
      t3 = SBOX[rotated];
      rconIndex += 1;
    } else if (nk > 6 && i % nk === 4) {
      // AES-256 applies an extra SubWord halfway through each key block.
      t0 = SBOX[t0];
      t1 = SBOX[t1];
      t2 = SBOX[t2];
      t3 = SBOX[t3];
    }

    const back = (i - nk) * 4;
    const here = i * 4;
    words[here] = words[back] ^ t0;
    words[here + 1] = words[back + 1] ^ t1;
    words[here + 2] = words[back + 2] ^ t2;
    words[here + 3] = words[back + 3] ^ t3;
  }

  return { words, rounds };
}

