/**
 * Python-flavoured exception types.
 *
 * The reference implementation is CPython, so its failure modes surface as
 * Python exceptions with specific messages and a specific traceback shape.
 * Modelling them explicitly keeps the CLI layer able to reproduce the
 * reference program's stderr and exit status without scattering ad-hoc string
 * literals through the code.
 */

/**
 * Base class for the emulated Python exceptions.  `pyName` is the type name
 * CPython would print in front of the message on the last traceback line.
 */
export class PythonError extends Error {
  /**
   * @param {string} pyName Python exception class name, e.g. `'ValueError'`
   * @param {string} message exception message
   */
  constructor(pyName, message) {
    super(message);
    this.name = pyName;
    this.pyName = pyName;
  }

  /** @returns {string} the final line CPython prints for this exception. */
  formatExceptionOnly() {
    return this.message === '' ? this.pyName : `${this.pyName}: ${this.message}`;
  }
}

/** Counterpart of Python's built-in `ValueError`. */
export class ValueError extends PythonError {
  /** @param {string} message exception message */
  constructor(message) {
    super('ValueError', message);
  }
}

/** Counterpart of Python's built-in `TypeError`. */
export class TypeError_ extends PythonError {
  /** @param {string} message exception message */
  constructor(message) {
    super('TypeError', message);
  }
}

/**
 * Counterpart of Python's `SystemExit`, raised by `argparse` when it prints
 * help or an error and stops the program.
 */
export class SystemExit extends PythonError {
  /** @param {number} code process exit status */
  constructor(code) {
    super('SystemExit', String(code));
    this.code = code;
  }
}

