/**
 * The AES block cipher itself (FIPS-197): a keyed permutation on 16-byte
 * blocks, with no notion of chaining, padding or streams.  Modes of operation
 * live in `./modes/`.
 *
 * The state is held as a flat 16-byte array in column-major order, matching the
 * byte order of the plaintext: byte `i` sits at row `i % 4`, column
 * `Math.floor(i / 4)`.
 */

import { INV_SBOX, SBOX } from './tables.mjs';
import { gmul, xtime } from './galois.mjs';
import { expandKey } from './key-schedule.mjs';
import { ValueError } from '../python/errors.mjs';

/** AES block size in bytes. */
export const BLOCK_SIZE = 16;

/**
 * XOR the round key starting at `offset` bytes into the state.
 *
 * @param {Uint8Array} state 16-byte state
 * @param {Uint8Array} roundKeys expanded key
 * @param {number} round round index
 */
function addRoundKey(state, roundKeys, round) {
  const offset = round * BLOCK_SIZE;
  for (let i = 0; i < BLOCK_SIZE; i += 1) {
    state[i] ^= roundKeys[offset + i];
  }
}

/**
 * Apply the given substitution box to every byte of the state.
 *
 * @param {Uint8Array} state 16-byte state
 * @param {Uint8Array} box substitution table
 */
function subBytes(state, box) {
  for (let i = 0; i < BLOCK_SIZE; i += 1) {
    state[i] = box[state[i]];
  }
}

/**
 * Rotate row `r` of the state left by `r` positions.
 *
 * @param {Uint8Array} state 16-byte state
 */
function shiftRows(state) {
  const source = state.slice();
  for (let column = 0; column < 4; column += 1) {
    for (let row = 0; row < 4; row += 1) {
      state[column * 4 + row] = source[((column + row) % 4) * 4 + row];
    }
  }
}

/**
 * Rotate row `r` of the state right by `r` positions.
 *
 * @param {Uint8Array} state 16-byte state
 */
function invShiftRows(state) {
  const source = state.slice();
  for (let column = 0; column < 4; column += 1) {
    for (let row = 0; row < 4; row += 1) {
      state[column * 4 + row] = source[((column - row + 4) % 4) * 4 + row];
    }
  }
}

/**
 * Multiply each column of the state by the fixed MixColumns matrix.
 *
 * @param {Uint8Array} state 16-byte state
 */
function mixColumns(state) {
  for (let column = 0; column < 4; column += 1) {
    const base = column * 4;
    const a0 = state[base];
    const a1 = state[base + 1];
    const a2 = state[base + 2];
    const a3 = state[base + 3];
    const parity = a0 ^ a1 ^ a2 ^ a3;
    state[base] = a0 ^ parity ^ xtime(a0 ^ a1);
    state[base + 1] = a1 ^ parity ^ xtime(a1 ^ a2);
    state[base + 2] = a2 ^ parity ^ xtime(a2 ^ a3);
    state[base + 3] = a3 ^ parity ^ xtime(a3 ^ a0);
  }
}

/**
 * Multiply each column of the state by the inverse MixColumns matrix.
 *
 * @param {Uint8Array} state 16-byte state
 */
function invMixColumns(state) {
  for (let column = 0; column < 4; column += 1) {
    const base = column * 4;
    const a0 = state[base];
    const a1 = state[base + 1];
    const a2 = state[base + 2];
    const a3 = state[base + 3];
    state[base] = gmul(a0, 14) ^ gmul(a1, 11) ^ gmul(a2, 13) ^ gmul(a3, 9);
    state[base + 1] = gmul(a0, 9) ^ gmul(a1, 14) ^ gmul(a2, 11) ^ gmul(a3, 13);
    state[base + 2] = gmul(a0, 13) ^ gmul(a1, 9) ^ gmul(a2, 14) ^ gmul(a3, 11);
    state[base + 3] = gmul(a0, 11) ^ gmul(a1, 13) ^ gmul(a2, 9) ^ gmul(a3, 14);
  }
}

/**
 * Raw AES: a single-block encrypt/decrypt primitive for a 128, 192 or 256 bit
 * key.  Rejecting a wrong-sized key with `ValueError('Invalid key size')`
 * mirrors the reference library.
 */
export class AES {
  /**
   * @param {Uint8Array} key 16, 24 or 32 raw key bytes
   */
  constructor(key) {
    const { words, rounds } = expandKey(key);
    /** @type {Uint8Array} expanded round keys */
    this.roundKeys = words;
    /** @type {number} number of cipher rounds */
    this.rounds = rounds;
    /** @type {number} key length in bytes */
    this.keySize = key.length;
  }

  /**
   * Encrypt exactly one block.
   *
   * @param {Uint8Array} block 16 plaintext bytes
   * @returns {Uint8Array} 16 ciphertext bytes
   * @throws {ValueError} when the block is not 16 bytes long
   */
  encryptBlock(block) {
    if (block.length !== BLOCK_SIZE) {
      throw new ValueError('plaintext block must be 16 bytes');
    }
    const state = Uint8Array.from(block);
    addRoundKey(state, this.roundKeys, 0);
    for (let round = 1; round < this.rounds; round += 1) {
      subBytes(state, SBOX);
      shiftRows(state);
      mixColumns(state);
      addRoundKey(state, this.roundKeys, round);
    }
    subBytes(state, SBOX);
    shiftRows(state);
    addRoundKey(state, this.roundKeys, this.rounds);
    return state;
  }

  /**
   * Decrypt exactly one block.
   *
   * @param {Uint8Array} block 16 ciphertext bytes
   * @returns {Uint8Array} 16 plaintext bytes
   * @throws {ValueError} when the block is not 16 bytes long
   */
  decryptBlock(block) {
    if (block.length !== BLOCK_SIZE) {
      throw new ValueError('ciphertext block must be 16 bytes');
    }
    const state = Uint8Array.from(block);
    addRoundKey(state, this.roundKeys, this.rounds);
    for (let round = this.rounds - 1; round >= 1; round -= 1) {
      invShiftRows(state);
      subBytes(state, INV_SBOX);
      addRoundKey(state, this.roundKeys, round);
      invMixColumns(state);
    }
    invShiftRows(state);
    subBytes(state, INV_SBOX);
    addRoundKey(state, this.roundKeys, 0);
    return state;
  }
}

