/**
 * Cipher Block Chaining mode.
 *
 * Each plaintext block is XORed with the previous ciphertext block before
 * being enciphered; the initialisation vector seeds the chain.  The chaining
 * value is instance state, so feeding a message through successive `encrypt`
 * calls one block at a time produces the same ciphertext as encrypting it in
 * one go.  No padding is applied — every call must supply a whole block.
 */

import { AES, BLOCK_SIZE } from '../block-cipher.mjs';
import { ValueError, withPyFrames } from '../../python/errors.mjs';

/**
 * Source locations inside the reference `pyaes/aes.py` that each failure
 * corresponds to.  They exist only so the CLI can reproduce the reference
 * program's traceback verbatim.
 */
const PY_FRAMES = {
  ivSize: [
    ['pyaes/aes.py', 381, '__init__'],
  ],
  keySize: [
    ['pyaes/aes.py', 385, '__init__'],
    ['pyaes/aes.py', 304, '__init__'],
    ['pyaes/aes.py', 134, '__init__'],
  ],
  blockSize: [
    ['pyaes/aes.py', 389, 'encrypt'],
  ],
};

/** AES in CBC mode, operating one block at a time and chaining across calls. */
export class AESModeOfOperationCBC {
  /** Human-readable mode name, mirroring the reference library. */
  static modeName = 'Cipher-Block Chaining (CBC)';

  /** Whether this mode consumes fixed-size blocks rather than a byte stream. */
  static blockMode = true;

  /**
   * @param {Uint8Array} key 16, 24 or 32 raw key bytes
   * @param {Uint8Array} [iv] 16-byte initialisation vector; all-zero if omitted
   */
  constructor(key, iv) {
    // The initialisation vector is validated before the key, so a call that
    // gets both wrong reports the IV.
    if (iv === undefined || iv === null) {
      this.lastCipherblock = new Uint8Array(BLOCK_SIZE);
    } else if (iv.length !== BLOCK_SIZE) {
      throw withPyFrames(
        new ValueError('initialization vector must be 16 bytes'),
        PY_FRAMES.ivSize,
      );
    } else {
      this.lastCipherblock = Uint8Array.from(iv);
    }

    try {
      /** @type {AES} */
      this.aes = new AES(key);
    } catch (error) {
      throw withPyFrames(error, PY_FRAMES.keySize);
    }
  }

  /**
   * Encipher one block and advance the chain.
   *
   * @param {Uint8Array} plaintext exactly 16 bytes
   * @returns {Uint8Array} 16 ciphertext bytes
   */
  encrypt(plaintext) {
    if (plaintext.length !== BLOCK_SIZE) {
      throw withPyFrames(
        new ValueError('plaintext block must be 16 bytes'),
        PY_FRAMES.blockSize,
      );
    }
    const xored = new Uint8Array(BLOCK_SIZE);
    for (let i = 0; i < BLOCK_SIZE; i += 1) {
      xored[i] = plaintext[i] ^ this.lastCipherblock[i];
    }
    const ciphertext = this.aes.encryptBlock(xored);
    this.lastCipherblock = ciphertext;
    return ciphertext;
  }

  /**
   * Decipher one block and advance the chain.
   *
   * @param {Uint8Array} ciphertext exactly 16 bytes
   * @returns {Uint8Array} 16 plaintext bytes
   */
  decrypt(ciphertext) {
    if (ciphertext.length !== BLOCK_SIZE) {
      throw new ValueError('ciphertext block must be 16 bytes');
    }
    const decrypted = this.aes.decryptBlock(ciphertext);
    const plaintext = new Uint8Array(BLOCK_SIZE);
    for (let i = 0; i < BLOCK_SIZE; i += 1) {
      plaintext[i] = decrypted[i] ^ this.lastCipherblock[i];
    }
    this.lastCipherblock = Uint8Array.from(ciphertext);
    return plaintext;
  }
}

