export class SystemExit extends PythonError {
  /** @param {number} code process exit status */
  constructor(code) {
    super('SystemExit', String(code));
    this.code = code;
  }
}

/**
 * @typedef {[string, number, string]} PyFrame
 *   A traceback frame as `[filename, lineNumber, functionName]`.
 */

/**
 * Tag an error with the library-side traceback frames CPython would have
 * unwound through, innermost last.  Frames belonging to the calling script are
 * prepended later, by the CLI layer.
 *
 * @param {Error} error the error being raised
 * @param {PyFrame[]} frames library frames, outermost first
 * @returns {Error} the same error, for use in a `throw` expression
 */
export function withPyFrames(error, frames) {
  if (!Array.isArray(error.pyFrames)) {
    error.pyFrames = frames;
  }
  return error;
}

/**
 * Render an exception the way CPython writes an unhandled one to stderr.
 *
 * @param {Error} error the exception, optionally carrying `pyFrames`
 * @param {PyFrame[]} [scriptFrames] frames of the calling script, outermost first
 * @returns {string} the traceback text, newline terminated
 */
export function formatTraceback(error, scriptFrames = []) {
  const frames = [...scriptFrames, ...(error.pyFrames ?? [])];
  const lines = ['Traceback (most recent call last):'];
  for (const [filename, lineNumber, functionName] of frames) {
    lines.push(`  File "${filename}", line ${lineNumber}, in ${functionName}`);
  }
  lines.push(
    error instanceof PythonError
      ? error.formatExceptionOnly()
      : `${error.name}: ${error.message}`,
  );
  return `${lines.join('\n')}\n`;
}

