/**
 * The pieces of Python's `bytes` semantics that this program depends on:
 * `str.encode()` (UTF-8) and `repr(bytes)`.
 *
 * Both are reimplemented from their observable behaviour rather than delegated
 * to a Node built-in, because the details that matter here — which byte values
 * `repr` escapes, which quote character it picks — are precisely the details a
 * general-purpose helper would not preserve.
 */

import { PythonError } from './errors.mjs';

/** Counterpart of Python's `UnicodeEncodeError`. */
export class UnicodeEncodeError extends PythonError {
  /** @param {string} message exception message */
  constructor(message) {
    super('UnicodeEncodeError', message);
  }
}

/**
 * Encode a JavaScript string to UTF-8 bytes, the way `str.encode()` does.
 *
 * JavaScript strings are UTF-16, so astral characters arrive as surrogate
 * pairs and are recombined here.  An unpaired surrogate is not encodable as
 * UTF-8; Python refuses it rather than substituting a replacement character, so
 * this does too.
 *
 * @param {string} text the string to encode
 * @returns {Uint8Array} the UTF-8 bytes
 * @throws {UnicodeEncodeError} on an unpaired surrogate
 */
export function encodeUtf8(text) {
  const bytes = [];
  for (let i = 0; i < text.length; i += 1) {
    let codePoint = text.charCodeAt(i);

    if (codePoint >= 0xd800 && codePoint <= 0xdbff) {
      const low = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
      if (low >= 0xdc00 && low <= 0xdfff) {
        codePoint = 0x10000 + ((codePoint - 0xd800) << 10) + (low - 0xdc00);
        i += 1;
      }
    }

    if (codePoint >= 0xd800 && codePoint <= 0xdfff) {
      const escaped = `\\u${codePoint.toString(16).padStart(4, '0')}`;
      throw new UnicodeEncodeError(
        `'utf-8' codec can't encode character '${escaped}' in position ${i}: ` +
          'surrogates not allowed',
      );
    }

    if (codePoint < 0x80) {
      bytes.push(codePoint);
    } else if (codePoint < 0x800) {
      bytes.push(0xc0 | (codePoint >> 6), 0x80 | (codePoint & 0x3f));
    } else if (codePoint < 0x10000) {
      bytes.push(
        0xe0 | (codePoint >> 12),
        0x80 | ((codePoint >> 6) & 0x3f),
        0x80 | (codePoint & 0x3f),
      );
    } else {
      bytes.push(
        0xf0 | (codePoint >> 18),
        0x80 | ((codePoint >> 12) & 0x3f),
        0x80 | ((codePoint >> 6) & 0x3f),
        0x80 | (codePoint & 0x3f),
      );
    }
  }
  return Uint8Array.from(bytes);
}

const APOSTROPHE = 0x27;
const QUOTATION_MARK = 0x22;
const BACKSLASH = 0x5c;

/**
 * Escape sequences Python prefers over the generic `\xHH` form.  Note that
 * `\a`, `\b`, `\f`, `\v` and `\0` are deliberately absent: `repr` writes those
 * bytes as `\x07`, `\x08`, `\x0c`, `\x0b` and `\x00`.
 */
const SHORT_ESCAPES = new Map([
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

/**
 * Format bytes the way Python's `repr()` does, e.g. `b'\\x0c+2\\xbe'`.
 *
 * The quote character is chosen the way CPython chooses it: single quotes
 * normally, but double quotes when the data contains an apostrophe and no
 * quotation mark — so the apostrophe can be left unescaped.  When the data
 * contains both, single quotes win and the apostrophes are escaped.
 *
 * @param {Uint8Array} bytes the byte string
 * @returns {string} the Python `repr` of those bytes
 */
export function bytesRepr(bytes) {
  let hasApostrophe = false;
  let hasQuotationMark = false;
  for (const byte of bytes) {
    if (byte === APOSTROPHE) hasApostrophe = true;
    else if (byte === QUOTATION_MARK) hasQuotationMark = true;
  }

  const quote = hasApostrophe && !hasQuotationMark ? QUOTATION_MARK : APOSTROPHE;
  const quoteChar = String.fromCharCode(quote);

  let body = '';
  for (const byte of bytes) {
    if (byte === quote || byte === BACKSLASH) {
      body += `\\${String.fromCharCode(byte)}`;
      continue;
    }
    const shortEscape = SHORT_ESCAPES.get(byte);
    if (shortEscape !== undefined) {
      body += shortEscape;
    } else if (byte < 0x20 || byte >= 0x7f) {
      body += `\\x${byte.toString(16).padStart(2, '0')}`;
    } else {
      body += String.fromCharCode(byte);
    }
  }

  return `b${quoteChar}${body}${quoteChar}`;
}

