#!/usr/bin/env node
/* Differential tester: /output/test17.mjs vs /workspace/dataset/test17_executable */
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test17_executable';
const MINE = ['/output/test17.mjs'];

function runRef(args) {
  const r = spawnSync(REF, args, { encoding: 'buffer', timeout: 30000 });
  return { out: r.stdout ?? Buffer.alloc(0), err: r.stderr ?? Buffer.alloc(0), code: r.status };
}
function runMine(args) {
  const r = spawnSync('node', [...MINE, ...args], { encoding: 'buffer', timeout: 30000 });
  return { out: r.stdout ?? Buffer.alloc(0), err: r.stderr ?? Buffer.alloc(0), code: r.status };
}
// PYI-<pid> differs by construction; normalise it away.
const norm = (b) => b.toString('binary').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

let pass = 0;
const fails = [];

function check(label, args) {
  const a = runRef(args);
  const b = runMine(args);
  const same =
    norm(a.out) === norm(b.out) && norm(a.err) === norm(b.err) && a.code === b.code;
  if (same) { pass += 1; return true; }
  fails.push({
    label, args,
    ref: { code: a.code, out: norm(a.out), err: norm(a.err) },
    mine: { code: b.code, out: norm(b.out), err: norm(b.err) },
  });
  return false;
}

// ---------------------------------------------------------------- generators
const PRINTABLE = Array.from({ length: 95 }, (_, i) => String.fromCharCode(32 + i))
  .filter((c) => c !== '�');
let seed = 0x2f6e2b1;
function rnd() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; }
function randStr(n, pool = PRINTABLE) {
  let s = '';
  for (let i = 0; i < n; i += 1) s += pool[Math.floor(rnd() * pool.length)];
  return s;
}

const cases = [];

// documented samples
cases.push(['sample1', ['--key', 'Ak.Gz@@He!c(Jd8,', '--iv', 'P#&03h.T(+m5_2XN', '--data', '};}w]2=?1C++Z+Eabi8?X_Iv2e:cAx^plV%)F%mHpL![!,c)']]);
cases.push(['sample2', ['--key', 'Usmp85)Gha0sr5]g', '--iv', '72w>!n%9I(:^}1fZ', '--data', 'W+Y0v<KiE7?f|#<UXxyZQEfkufrwXb*e%!G!7&x-Nnf=A_.!']]);
cases.push(['sample3', ['--key', '_FKMBskR,{E,jWpx', '--iv', 'c.*$.wu  zE.<iDN', '--data', '2N3a>*HW==(w-HRU5;EW@V,&X<BS :cHd<#MKOe5hE6(Z0p@']]);
cases.push(['sample4', ['--key', ':7+ZBj}xgYw<s*#G', '--iv', ')gxmez*lgS03n]Yq', '--data', ')E1cij6 1cX#@7:]+].,UmvhlLEX-bAD6{pt(pzDS%scKBdE']]);

// random AES-128, 3 blocks (the documented shape)
for (let i = 0; i < 220; i += 1) {
  cases.push([`rand128-3blk#${i}`, ['--key', randStr(16), '--iv', randStr(16), '--data', randStr(48)]]);
}
// random AES-128/192/256 with 0..8 blocks
for (let i = 0; i < 160; i += 1) {
  const ks = [16, 24, 32][i % 3];
  const blocks = i % 9;
  cases.push([`rand-k${ks}-b${blocks}#${i}`, ['--key', randStr(ks), '--iv', randStr(16), '--data', randStr(16 * blocks)]]);
}
// keys/ivs/data biased toward quote and backslash bytes to exercise repr
const QUOTEY = ['\'', '"', '\\', 'a', 'Z', '~', ' ', '0'];
for (let i = 0; i < 120; i += 1) {
  cases.push([`quotey#${i}`, ['--key', randStr(16, QUOTEY), '--iv', randStr(16, QUOTEY), '--data', randStr(32, QUOTEY)]]);
}
// long data (100 blocks)
cases.push(['long-100blk', ['--key', randStr(16), '--iv', randStr(16), '--data', randStr(1600)]]);
cases.push(['long-257blk', ['--key', randStr(32), '--iv', randStr(16), '--data', randStr(16 * 257)]]);

// multibyte UTF-8
cases.push(['utf8-key16', ['--key', 'é'.repeat(8), '--iv', '0123456789abcdef', '--data', '0123456789abcdef']]);
cases.push(['utf8-iv16', ['--key', '0123456789abcdef', '--iv', 'é'.repeat(8), '--data', '0123456789abcdef']]);
cases.push(['utf8-data16', ['--key', '0123456789abcdef', '--iv', '0123456789abcdef', '--data', 'é'.repeat(8)]]);
cases.push(['utf8-data32', ['--key', '0123456789abcdef', '--iv', '0123456789abcdef', '--data', 'é'.repeat(16)]]);
cases.push(['utf8-3byte', ['--key', '0123456789abcdef', '--iv', '0123456789abcdef', '--data', '中'.repeat(16)]]); // 48 bytes
cases.push(['utf8-4byte', ['--key', '0123456789abcdef', '--iv', '0123456789abcdef', '--data', '😀'.repeat(8)]]); // 32 bytes
cases.push(['utf8-mixed', ['--key', 'aé中😀aaa', '--iv', '0123456789abcdef', '--data', 'x😀中éy'.repeat(2)]]);
cases.push(['utf8-key24', ['--key', 'é'.repeat(12), '--iv', '0123456789abcdef', '--data', '0123456789abcdef']]);
cases.push(['utf8-key-odd', ['--key', 'é'.repeat(7) + 'a', '--iv', '0123456789abcdef', '--data', '0123456789abcdef']]);
cases.push(['utf8-key-bad', ['--key', 'é'.repeat(9), '--iv', '0123456789abcdef', '--data', '0123456789abcdef']]);
cases.push(['utf8-data-notmult', ['--key', '0123456789abcdef', '--iv', '0123456789abcdef', '--data', 'é'.repeat(9)]]);

// error paths: key sizes
for (const n of [0, 1, 2, 8, 15, 17, 20, 23, 25, 31, 33, 48, 64]) {
  cases.push([`keysize-${n}`, ['--key', 'k'.repeat(n), '--iv', '0123456789abcdef', '--data', '0123456789abcdef']]);
}
// error paths: iv sizes
for (const n of [0, 1, 15, 17, 32]) {
  cases.push([`ivsize-${n}`, ['--key', '0123456789abcdef', '--iv', 'v'.repeat(n), '--data', '0123456789abcdef']]);
}
// error paths: data sizes
for (const n of [1, 2, 15, 17, 31, 33, 47, 49, 63]) {
  cases.push([`datasize-${n}`, ['--key', '0123456789abcdef', '--iv', '0123456789abcdef', '--data', 'd'.repeat(n)]]);
}
// combinations of bad key + bad iv + bad data (ordering of validation)
cases.push(['bad-all', ['--key', 'x', '--iv', 'y', '--data', 'z']]);
cases.push(['bad-key-iv', ['--key', 'x', '--iv', 'y', '--data', '0123456789abcdef']]);
cases.push(['bad-key-data', ['--key', 'x', '--iv', '0123456789abcdef', '--data', 'z']]);
cases.push(['bad-iv-data', ['--key', '0123456789abcdef', '--iv', 'y', '--data', 'z']]);
cases.push(['empty-all', ['--key', '', '--iv', '', '--data', '']]);
cases.push(['empty-data-ok', ['--key', '0123456789abcdef', '--iv', '0123456789abcdef', '--data', '']]);

// ------------------------------------------------------------ argparse cases
const K = '0123456789abcdef';
const argparseCases = [
  [],
  ['-h'], ['--help'], ['--he'], ['--hel'], ['--h'],
  ['-h', '--key', 'a'], ['--zzz', '-h'], ['--key', K, '-h'],
  ['--key', K], ['--iv', K], ['--data', K],
  ['--key', K, '--iv', K],
  ['--key', K, '--data', K],
  ['--iv', K, '--data', K],
  ['--key'], ['--iv'], ['--data'],
  ['--key', K, '--iv', K, '--data'],
  ['--k', K, '--i', K, '--d', K],
  ['--ke', K, '--i', K, '--da', K],
  [`--key=${K}`, `--iv=${K}`, `--data=${K}`],
  ['--key=', '--iv', K, '--data', ''],
  ['--key', K, '--iv', K, '--data='],
  ['--key', K, '--key', 'ZZZZZZZZZZZZZZZZ', '--iv', K, '--data', K],
  ['--key', K, '--iv', K, '--data', K, 'extra'],
  ['--key', K, '--iv', K, '--data', K, 'e1', 'e2', '--foo', 'bar'],
  ['hello'],
  ['-k', 'x'],
  ['-x'],
  ['--key', K, '--iv', K, '--data', '--'],
  ['--key', K, '--iv', K, '--data', '--', K],
  ['--key', K, '--iv', K, '--data', K, '--'],
  ['--', '--key', K, '--iv', K, '--data', K],
