cases.push(['sample1', ['--key', 'Ak.Gz@@He!c(Jd8,', '--iv', 'P#&03h.T(+m5_2XN', '--data', '};}w]2=?1C++Z+Eabi8?X_Iv2e:cAx^plV%)F%mHpL![!,c)']]);
cases.push(['sample2', ['--key', 'Usmp85)Gha0sr5]g', '--iv', '72w>!n%9I(:^}1fZ', '--data', 'W+Y0v<KiE7?f|#<UXxyZQEfkufrwXb*e%!G!7&x-Nnf=A_.!']]);
cases.push(['sample3', ['--key', '_FKMBskR,{E,jWpx', '--iv', 'c.*$.wu  zE.<iDN', '--data', '2N3a>*HW==(w-HRU5;EW@V,&X<BS :cHd<#MKOe5hE6(Z0p@']]);
cases.push(['sample4', ['--key', ':7+ZBj}xgYw<s*#G', '--iv', ')gxmez*lgS03n]Yq', '--data', ')E1cij6 1cX#@7:]+].,UmvhlLEX-bAD6{pt(pzDS%scKBdE']]);

