#!/usr/bin/env node
/**
 * Entry point — the Node.js counterpart of `test17.py`.
 *
 * Encrypts `--data` with AES-CBC under `--key` and `--iv`, one 16-byte block at
 * a time, and prints the Python `repr()` of each ciphertext block:
 *
 *   node test17.mjs --key <16 bytes> --iv <16 bytes> --data <n*16 bytes>
 *
 * Everything it needs is in `./lib`; there are no third-party dependencies and
 * no use of `node:crypto`.
 */

import { run } from './lib/app.mjs';

/**
 * Buffered stdout/stderr sinks.  CPython block-buffers a redirected stdout and
 * flushes it at exit, so collecting the output and writing it once keeps the
 * interleaving — and the behaviour on a closed pipe — the same.
 */
const chunks = { out: [], err: [] };

const exitCode = run(process.argv.slice(2), {
  writeOut: (text) => chunks.out.push(text),
  writeErr: (text) => chunks.err.push(text),
}, process.pid);

if (chunks.out.length > 0) process.stdout.write(chunks.out.join(''));
if (chunks.err.length > 0) process.stderr.write(chunks.err.join(''));

process.exitCode = exitCode;

