/**
 * `argparse`'s help formatter: the part that turns declared options into the
 * `usage:` line and the options list, and wraps both to the terminal width.
 *
 * Width matters more than it looks like it should.  The usage line is printed
 * ahead of *every* error message, so a narrow terminal changes the output of
 * ordinary failed invocations, not just of `--help`.
 *
 * This formatter models a parser with optional arguments only, which is what
 * the program it serves has; positionals are not represented.
 */

/** What `argparse` prints before the usage line. */
const PREFIX = 'usage: ';

/** Indentation step for the options list. */
const INDENT_INCREMENT = 2;

/** Upper bound on how far right the help column may start. */
const MAX_HELP_POSITION = 24;

/** Narrowest the help text column is ever allowed to become. */
const MIN_HELP_WIDTH = 11;

/** Terminal width assumed when there is no terminal to ask. */
const FALLBACK_COLUMNS = 80;

/**
 * Accepts exactly what Python's `int()` accepts: surrounding whitespace, an
 * optional sign, then digits.  `'  40  '` and `'+40'` are widths; `'40abc'` is
 * not, and is ignored rather than truncated.
 */
const PYTHON_INT = /^\s*[+-]?\d+\s*$/;

/**
 * The terminal width `shutil.get_terminal_size()` would report: `COLUMNS` if it
 * holds a positive integer, else the real terminal's width, else 80.
 *
 * @param {Record<string, string|undefined>} [env] environment to read
 * @param {{columns?: number}} [stream] stream to measure, normally stdout
 * @returns {number} width in columns
 */
export function terminalColumns(env = process.env, stream = process.stdout) {
  const raw = env.COLUMNS;
  if (raw !== undefined && PYTHON_INT.test(raw)) {
    const columns = Number.parseInt(raw, 10);
    if (columns > 0) return columns;
  }
  const measured = stream?.columns;
  return typeof measured === 'number' && measured > 0 ? measured : FALLBACK_COLUMNS;
}

/**
 * Greedy word wrap, matching `textwrap.wrap`: runs of whitespace collapse to a
 * single space, and a word too long for any line is split across lines after
 * filling out whatever room is left on the current one.
 *
 * @param {string} text the text to wrap
 * @param {number} width the column budget
 * @returns {string[]} the wrapped lines, without trailing newlines
 */
export function wrapText(text, width) {
  const limit = Math.max(width, 1);
  const words = text.replace(/\s+/g, ' ').trim().split(' ').filter((word) => word !== '');

  const lines = [];
  let line = '';
  for (const word of words) {
    let rest = word;
    if (line !== '') {
      if (line.length + 1 + rest.length <= limit) {
        line += ` ${rest}`;
        continue;
      }
      if (rest.length > limit) {
        const room = limit - line.length - 1;
        if (room > 0) {
          line += ` ${rest.slice(0, room)}`;
          rest = rest.slice(room);
        }
      }
      lines.push(line);
      line = '';
    }
    while (rest.length > limit) {
      lines.push(rest.slice(0, limit));
      rest = rest.slice(limit);
    }
    line = rest;
  }
  if (line !== '') lines.push(line);
  return lines;
}

/**
 * Split a usage body into the pieces `argparse` is willing to break between: a
 * bracketed or parenthesised group stays whole, everything else splits on
 * whitespace.  So `[-h]` survives as one piece while `--key KEY` becomes two.
 *
 * @param {string} usageBody the rendered options, space separated
 * @returns {string[]} the wrappable pieces
 */
function splitUsageParts(usageBody) {
  return usageBody.match(/\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g) ?? [];
}

/**
 * Pack `parts` into lines of at most `textWidth` columns, indenting every line
 * with `indent`.
 *
 * When `prefix` is given, the first line is assumed to sit after that prefix
 * instead of after the indent, and is returned without the indent — that is how
 * the usage line gets to start on the same line as `usage: `.
 *
 * @param {string[]} parts the pieces to pack
 * @param {string} indent leading whitespace for each line
 * @param {number} textWidth the column budget
 * @param {string|null} prefix text the first line follows, if any
 * @returns {string[]} the packed lines
 */
function packLines(parts, indent, textWidth, prefix) {
  const lines = [];
  let line = [];
  let lineLength = (prefix === null ? indent.length : prefix.length) - 1;

  for (const part of parts) {
    if (lineLength + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLength = indent.length - 1;
    }
    line.push(part);
    lineLength += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (prefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
  return lines;
}

/** Renders the usage line and options list for a set of optional arguments. */
export class HelpFormatter {
  /**
   * @param {string} prog program name to show
   * @param {number} columns terminal width, as {@link terminalColumns} reports it
   */
  constructor(prog, columns) {
    /** @type {string} */
    this.prog = prog;
    // argparse budgets two columns fewer than the terminal actually has.
    /** @type {number} */
    this.width = columns - 2;
  }

  /**
   * @param {import('./argparse.mjs').Action} action the option to render
   * @returns {string} how the option appears in the usage line
   */
  actionUsage(action) {
    const [first] = action.optionStrings;
    const body = action.nargs === 0 ? first : `${first} ${action.metavar}`;
    return action.required ? body : `[${body}]`;
  }

  /**
   * @param {import('./argparse.mjs').Action} action the option to render
   * @returns {string} how the option appears in the options list
   */
  actionInvocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
  }

  /**
   * @param {import('./argparse.mjs').Action[]} actions the declared options
   * @returns {string} the `usage: ...` line, wrapped, newline terminated
   */
  formatUsage(actions) {
    const body = actions.map((action) => this.actionUsage(action)).join(' ');
    const usage = [this.prog, body].filter((piece) => piece !== '').join(' ');
    const textWidth = this.width;

    if (PREFIX.length + usage.length <= textWidth) {
      return `${PREFIX}${usage}\n`;
    }

    const parts = splitUsageParts(body);
    let lines;
    if (PREFIX.length + this.prog.length <= 0.75 * textWidth) {
      // The program name is short enough to keep options on its line.
